// Pega a resposta completa do SerpApi (nó HTTP)
const response = $input.first().json;

// 1. Extrai as médias anuais (O mais importante para saber o que é mais popular)
const mediasAnuais = response.interest_over_time?.averages || [];

// 2. Extrai apenas as últimas 4 semanas (1 mês) para ver a tendência recente, economizando 90% dos tokens
const timelineCompleta = response.interest_over_time?.timeline_data || [];
const ultimas4Semanas = timelineCompleta.slice(-4).map(semana => {
    return {
        data: semana.date,
        valores: semana.values.map(v => ({ 
            query: v.query, 
            valor: v.extracted_value 
        }))
    };
});

// 3. Devolve um JSON limpo, leve e direto ao ponto para o Agente de IA ler
return [{
    json: {
        tendencia_google: {
            medias_anuais: mediasAnuais,
            tendencia_recente_ultimo_mes: ultimas4Semanas
        }
    }
}];

const items = $input.all();
const googleSearchData = [];

items.forEach(item => {
    const json = item.json;
    let ppaList = [];
    let topTitulos = [];
    let aiResumo = "";

    // 1. Extrair People Also Ask (A dor real do público)
    if (json.peopleAlsoAsk && Array.isArray(json.peopleAlsoAsk)) {
        ppaList = json.peopleAlsoAsk.map(q => ({
            pergunta: q.question,
            // Pega só o comecinho da resposta para economizar tokens
            resposta_curta: q.answer ? q.answer.substring(0, 150) + "..." : "Sem resposta direta"
        }));
    }

    // 2. Extrair APENAS os Títulos do Top 3 (Para a IA criar uma manchete melhor)
    if (json.organicResults && Array.isArray(json.organicResults)) {
        topTitulos = json.organicResults.slice(0, 3).map(res => res.title);
    }

    // 3. Extrair o Resumo da IA do Google (Contexto rápido)
    if (json.aiOverview && json.aiOverview.content) {
        // Limita a 300 caracteres para não inundar o prompt
        aiResumo = json.aiOverview.content.substring(0, 300) + "..."; 
    }

    // Monta o pacote final ultra-enxuto
    googleSearchData.push({
        termo_pesquisado: json.searchQuery ? json.searchQuery.term : "Busca",
        duvidas_do_publico_PAA: ppaList,
        concorrencia_top3_titulos: topTitulos,
        resumo_ia_google: aiResumo
    });
});

return [{
    json: {
        pesquisa_profunda_google: googleSearchData
    }
}];

// Pega todos os itens de entrada do nó anterior
const items = $input.all();
const resultados = [];
let todasAsKeywords = [];

// 1. Extrai TODAS as palavras-chave de todos os arrays da entrada
for (const item of items) {
  if (item.json && item.json.query) {
    try {
      const arraysDeKeywords = JSON.parse(item.json.query);

      for (const obj of arraysDeKeywords) {
        if (obj.keywords_to_search && Array.isArray(obj.keywords_to_search)) {
          // Adiciona todas as palavras-chave na nossa lista geral
          todasAsKeywords.push(...obj.keywords_to_search);
        }
      }
    } catch (error) {
      console.error("Erro ao fazer o parse da string JSON:", error);
    }
  }
}

// 2. Agrupa a lista de 5 em 5 e junta com vírgulas
const TAMANHO_DO_LOTE = 5; // Máximo de palavras-chave por envio para a SerpAPI

for (let i = 0; i < todasAsKeywords.length; i += TAMANHO_DO_LOTE) {
  // Corta um pedaço da lista (ex: do 0 ao 5, do 5 ao 10...)
  const lote = todasAsKeywords.slice(i, i + TAMANHO_DO_LOTE);

  // Junta as palavras desse lote separando por vírgula
  resultados.push({
    json: {
      search_query: lote.join(", ")
    }
  });
}

// Retorna os lotes prontos para o próximo nó
return resultados;

// Pega os itens de entrada
const items = $input.all();
let todasAsKeywords = [];

// 1. Extrai TODAS as palavras-chave da string JSON
for (const item of items) {
  if (item.json && item.json.query) {
    try {
      const arraysDeKeywords = JSON.parse(item.json.query);

      for (const obj of arraysDeKeywords) {
        if (obj.keywords_to_search && Array.isArray(obj.keywords_to_search)) {
          // Adiciona as palavras na nossa lista geral
          todasAsKeywords.push(...obj.keywords_to_search);
        }
      }
    } catch (error) {
      console.error("Erro ao fazer o parse da string JSON:", error);
    }
  }
}

// 2. Prepara o formato exato exigido pelo Apify Google Search Scraper
// O Apify exige as buscas separadas por quebra de linha (\n) em uma única string
const apifyQueries = todasAsKeywords.join("\n");

// 3. Retorna 1 único item para rodar o Actor do Apify uma única vez (economiza créditos)
return [
  {
    json: {
      queries: apifyQueries,
      // Já deixei preparadas as variáveis de otimização de busca para PT-BR
      countryCode: "br",
      languageCode: "pt-BR",
      maxPagesPerQuery: 1, // Pega apenas a primeira página do Google
      resultsPerPage: 10   // Top 10 resultados de cada termo
    }
  }
];

